pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testRegression_property() public {
        vm.deal(address(0x1234), 1 ether);
        vm.prank(address(0x1234));
        (bool okDeposit, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("deposit()"));
        assertTrue(okDeposit);

        vm.prank(address(0x1234));
        (bool okWithdraw, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(okWithdraw);
    }
}
